<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageSendAtVO;

trait MessageSendAtAccessor
{
    private ?MessageSendAtVO $_sendAt = null;
    public function getSendAt(): ?\DateTimeImmutable
    {
        return $this->_sendAt?->value();
    }
    public function sendAt(): ?MessageSendAtVO
    {
        return $this->_sendAt;
    }
    public function isSendAtChanged(?self $original = null): bool
    {
        return null !== $this->_sendAt && !$this->_sendAt->equals($original?->_sendAt);
    }
    public function withSendAt(MessageSendAtVO|\DateTimeImmutable|null $sendAt): self
    {
        $copy = clone $this;
        $copy->_sendAt = MessageSendAtVO::from($sendAt);
        return $copy;
    }
}
